("02","hdfs_cli","HDFS CLI и управление данными",["mkdir","put","copyFromLocal","get","cat","text","head","tail","ls","du","count","stat","test","cp","mv","rm to trash","expunge","touchz","appendToFile","getmerge","setrep","checksum","find","glob","permissions","owner","ACL","snapshot commands","distcp concept","CLI pipeline"]),
